import numpy as np
def equation(t, A, params):
    num = (params[0] + params[1]*t + params[2]*A + params[3]*A**2 + params[4]*A**3
           + params[5]*t*A + params[6]*t*A**2 + params[7]*t**2)
    return num/(1 + params[8]*t + params[9]*A)

